  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT DISTINCT status, COUNT(*) as cnt FROM orders GROUP BY status ORDER BY cnt DESC",
      "why": "Check what order statuses exist in the system — if 'confirmed' never appears and only 'paid' does, the invariant query may be checking for a status string that the current code no longer writes, possibly changed by the payment-service v1.1 deploy or an order-service behaviour change"
    }
  ],
  "hypotheses": [
    {
      "service": "payment-service",
      "kind": "bad_deploy",
      "mechanism": "The v1.1 deploy of payment-service at t=506 changed the order status written on payment capture from 'confirmed' to 'paid', causing the I1 invariant check (which looks for status='confirmed') to flag these rows as violations even though orders are being updated.",
      "supporting": ["E1", "E3", "E9"],
      "refuting": ["E10"],
      "explains": ["I1_payment_has_order"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "payment-service"}},
        {"action": "replay_payment_confirmations", "params": {}}
      ]
    }
  ],
  "summary": "Payment-service v1.1 likely changed the order confirmation status value from 'confirmed' to 'paid', causing the invariant check to flag captured payments whose orders are updated but not to the expected 'confirmed' status."
}
